    val MAP: Map<String, DuaText> = mapOf(
        "dua_breaking_fast" to DuaText("উপবাস ভংগ কৰাৰ পিছত", "পিয়াহ আঁতৰি গৈছে, শিৰাবোৰ তিয়াই গৈছে, আৰু যদি আল্লাহৰ ইচ্ছা হয় তেন্তে পুৰস্কাৰ নিশ্চিত কৰা হৈছে।", "ইফতৰৰ সময়ত।", "নবী (ছাঃ)-এ তেওঁৰ উপবাস ভংগ কৰাৰ সময়ত এই কথা কৈছিল।"),
        "dua_new_clothes" to DuaText("নতুন কাপোৰ পিন্ধা", "হে আল্লাহ, সকলো প্ৰশংসা তোমাৰ; তুমি মোক এইটো পিন্ধাইছা। মই তোমাৰ ওচৰত ইয়াৰ ভাল আৰু ভাল বিচাৰো যাৰ বাবে ইয়াক নিৰ্মাণ কৰা হৈছিল, আৰু মই ইয়াৰ বেয়া আৰু বেয়াৰ পৰা তোমাৰ ওচৰত আশ্ৰয় বিচাৰো যাৰ বাবে ইয়াক নিৰ্মাণ কৰা হৈছিল।", "নতুন কাপোৰ পিন্ধাৰ সময়ত (ইয়াৰ নাম দিয়া, যেনে চাৰ্ট বা পাগুৰি)।", "নবী (ছাঃ)-এ নতুন কাপোৰ পিন্ধি এই দুআ কৰিছিল। (কাপোৰ পিন্ধাৰ বাবে দৈনিক দুআ'কাপোৰ পিন্ধা'ৰ অধীনত হয়)।"),
        "dua_rabbana_atina" to DuaText("এই পৃথিৱী আৰু পৰৱৰ্তী সময়ত ভাল।", "হে আমাৰ প্ৰভু, আমাক এই পৃথিৱীত ভাল আৰু পৰৱৰ্তী সময়ত ভাল দিয়ক, আৰু আমাক জুইৰ শাস্তিৰ পৰা ৰক্ষা কৰক।", "নবী সল্লল্লাহু অলৈহি ঵সলে প্ৰায়ে দ্বায় তৈয়াৰ কৰিছিল।", "এক দুআ যিয়ে এই পৃথিৱী আৰু পৰৱৰ্তী সময়ৰ সকলো ভাল বস্তু সংগ্ৰহ কৰে।"),
        "dua_rabbi_zidni_ilma" to DuaText("জ্ঞান বৃদ্ধি", "হে মোৰ প্ৰভু, মোক জ্ঞান বৃদ্ধি কৰা।", "জ্ঞান বৃদ্ধিৰ বাবে।", "আল্লাহে নবী (ছাঃ)-ক জ্ঞানৰ বাহিৰে আন একো বৃদ্ধিৰ বাবে অনুৰোধ কৰিবলৈ আদেশ দিছিল।"),
        "dua_musa_sharh_sadr" to DuaText("বুকু খোলা (মুসা এ. এছ.)", "হে মোৰ প্ৰভু, মোৰ বাবে মোৰ বুকু বহল কৰা, মোৰ বাবে মোৰ কাম সহজ কৰা, আৰু মোৰ জিভাৰ পৰা গাঁঠিটো খুলি দিয়া যাতে তেওঁলোকে মোৰ কথা বুজি পায়।", "পৰীক্ষাৰ আগতে, ভাষণ বা যিকোনো কঠিন কাম।", "নবী মুসা (আৰু. আৰ.)-ৰ দুআ-হৃদয়ৰ শান্তি আৰু নিজৰ কামত সহজতা।"),
        "dua_la_tuzigh" to DuaText("হৃদয়ৰ স্থিৰতা", "হে আমাৰ প্ৰভু, তুমি আমাক পথ দেখুৱাই দিয়াৰ পিছত আমাৰ হৃদয়বোৰ বিচ্যুত নহ'বলৈ দিয়ক, আৰু নিজৰ ফালৰ পৰা আমাক দয়া কৰা। নিঃসন্দেহ তুমিই হ'লা সৰ্বশক্তিশালী।", "নিৰ্দেশনাৰ ওপৰত দৃঢ়তাৰ বাবে।", "বিশ্বাসত দৃঢ় হৈ থকাৰ বাবে এটা দুআ।"),
        "dua_ya_muqallib" to DuaText("হে টাৰ্নাৰ অৱ হাৰ্টছ", "হে হৃদয়ৰ টাৰ্নাৰ, মোৰ হৃদয় আপোনাৰ ধৰ্মৰ ওপৰত দৃঢ় ৰাখক।", "নবী (ছাঃ)-এ প্ৰায়ে এই দুআ কৰিছিল।", "উম্ম ছালামাহ (আৰ. এ.)-ৰ মতে, নবী ছলীহ আলীহ ৱাছলে প্ৰায়ে দুআ কৰিছিল।"),
        "dua_la_tuakhidhna" to DuaText("ছুৰাহ আল-বাকাৰাহৰ শেষ আয়াতসমূহ", "হে আমাৰ প্ৰভু, আমি পাহৰি গ \"লে বা ভুল কৰিলে আমাক শাস্তি নিদিবা। হে আমাৰ প্ৰভু, তুমি আমাৰ ওপৰত আমাৰ পূৰ্বৰ লোকসকলৰ ওপৰত দিয়া বোজাৰ দৰে বোজা নলবা। হে আমাৰ প্ৰভু, আমি সহ্য কৰিব নোৱাৰা বোজাৰে আমাৰ ওপৰত বোজা নলগা। আমাক ক্ষমা কৰা, আমাক ক্ষমা কৰা আৰু আমাৰ ওপৰত দয়া কৰা। তুমি আমাৰ ৰক্ষক, গতিকে অবিশ্বাসী লোকসকলৰ বিৰুদ্ধে আমাক সহায় কৰা।", "শুৱাৰ আগতে ৰাতি-ছুৰাহ আল-বাকাৰাহৰ শেষ দুটা আয়াত।", "যিজনে নিশা ছুৰাহ আল-বাকাৰাহৰ শেষ দুটা আয়াত পাঠ কৰে, সেইয়া তেওঁক যথেষ্ট হ'ব।"),
        "dua_visiting_sick" to DuaText("ৰোগীজনক সাক্ষাৎ কৰা", "মই শক্তিশালী আৰু শক্তিশালী সিংহাসনৰ প্ৰভু আল্লাহলৈ আপোনাক সুস্থ কৰিবলৈ অনুৰোধ জনাইছো।", "ৰোগীজনক চাবলৈ যোৱাৰ সময়ত সাতবাৰ।", "যদি মৃত্যুৰ সময় অহা নাই, তেন্তে ঈশ্বৰে তেওঁক সুস্থ কৰি তুলিব।"),
        "dua_ruqyah_pain" to DuaText("শাৰীৰিক বিষৰ বাবে", "মই যি অনুভৱ কৰোঁ আৰু যি ভয় কৰোঁ তাৰ দুষ্টতাৰ পৰা মই আল্লাহ আৰু তেওঁৰ শক্তিৰ আশ্ৰয় বিচাৰোঁ।", "আপোনাৰ হাতখন য'ত বিষ হয় তাত ৰাখক, তিনিবাৰ বিসমিল্লাহ কওক, তাৰ পিছত এই দুৱা সাতবাৰ কওক।", "নবী ছলীহ আলীহ ৱাছলে ইয়াক উথমান ইবন আবিল -'আছ (আৰ. এ.) ক বিষৰ বাবে শিকাইছিল।"),
        "dua_ruqyah_nabawi" to DuaText("ৰোগীৰ বাবে ভবিষ্যদ্বাণীমূলক ৰুকিয়া", "হে মানুহৰ প্ৰভু, হে আল্লাহ! ক্ষতি আঁতৰাই দিয়ক আৰু চিকিৎসা কৰক, কিয়নো তুমিহে চিকিৎসা কৰা; তোমাৰ চিকিৎসাৰ বাহিৰে কোনো চিকিৎসা নাই-এটা চিকিৎসা যি কোনো ৰোগ এৰি নাযায়।", "ৰোগীজনৰ ওপৰত হাত থৈ যোৱাৰ সময়ত।", "নবী (ছাঃ)-এ তেওঁৰ পৰিয়ালৰ অসুস্থ সদস্যসকলক সাক্ষাৎ কৰাৰ সময়ত এই পাঠ কৰিছিল।"),
        "dua_kalimat_tammat" to DuaText("নিখুঁত শব্দত শৰণাৰ্থ সন্ধান কৰা", "মই তেওঁ সৃষ্টি কৰা দুষ্টতাৰ পৰা আল্লাহৰ নিখুঁত বাক্যত আশ্ৰয় বিচাৰো।", "কোনো ঠাইত বা সন্ধিয়া ৰৈ থকাৰ সময়ত।", "যিজনে এটা ঠাইত ৰৈ এই কথা কয়, তেওঁ এৰি যোৱালৈকে তেওঁৰ কোনো ক্ষতি নহ \"ব।"),
        "dua_evil_eye" to DuaText("শিশুৰ বাবে সুৰক্ষা (দুষ্ট চকু)", "মই আপোনালোক দুয়োৰে বাবে প্ৰতিটো শয়তান আৰু প্ৰতিটো বিষাক্ত প্ৰাণীৰ পৰা আৰু প্ৰতিটো ক্ষতিকাৰক চকুৰ পৰা আল্লাহৰ নিখুঁত বাক্যত সুৰক্ষা বিচাৰো।", "নবী ছলীহ আলীহ ৱাছলে হাছান আৰু হুছাইনৰ ওপৰত এই পাঠ কৰিছিল।", "শিশুক দুৰ্বল চকু আৰু ক্ষতিৰ পৰা সুৰক্ষা দিবলৈ এটা সুন্নাহ দুআ (এটা শিশুৰ বাবে'উধুকা'বুলি কোৱা হয়)।"),
        "dua_seeing_afflicted" to DuaText("বিচাৰত কাৰোবাক দেখা পোৱা", "সকলো প্রশংসা সেই আল্লাহৰ বাবে যিজনে মোক তেওঁৰ পৰীক্ষাৰ পৰা ৰক্ষা কৰিছে, আৰু তেওঁৰ সৃষ্টিৰ বেছিভাগৰ ওপৰত মোৰ ওপৰত অনুৰাগ কৰিছে।", "কাৰোবাক বিচাৰত দেখা পোৱাৰ পিছত (ইয়াক নিজকে শান্তভাৱে কওক)।", "যিজনে কয় যে ইয়াক সেই বিচাৰৰ পৰা সুৰক্ষিত ৰখা হৈছে।"),
        "dua_istikhara" to DuaText("ছালাত আল-ইস্তিকাৰা", "হে আল্লাহ, মই তোমাৰ জ্ঞানৰ জৰিয়তে ভাল বিচাৰোঁ, মই তোমাৰ শক্তিৰ জৰিয়তে সামৰ্থ্য বিচাৰোঁ, আৰু মই তোমাৰ মহান অনুৰোধ বিচাৰোঁ। তোমাৰ ক্ষমতা আছে আৰু মোৰ একো নাই; তুমি জানো আৰু মই নাজানো, আৰু তুমি অদৃশ্যৰ বিষয়ে অৱগত। হে আল্লাহ, যদি তোমাৰ জ্ঞানত এই বিষয়টো (মনত পেলাই) মোৰ ধৰ্ম, মোৰ জীৱন আৰু মোৰ শেষৰ বাবে ভাল হয়, তেন্তে মোৰ বাবে ইয়াক আদেশ দিয়ক, মোৰ বাবে ইয়াক সহজ কৰি দিয়ক আৰু মোক ইয়াত আশীৰ্বাদ দিয়ক। আৰু যদি তোমাৰ জ্ঞানত এই বিষয়টো মোৰ ধৰ্ম, মোৰ জীৱন আৰু মোৰ শেষৰ বাবে বেয়া হয়, তেন্তে ইয়াক মোৰ পৰা আঁতৰাই দিয়ক আৰু মোক ইয়াৰ পৰা আঁতৰাই দিয়ক, আৰু মোৰ বাবে যি ঠাইত ভাল হ'ব পাৰে তাৰ বাবে আদেশ দিয়ক।", "স্বেচ্ছামূলক প্ৰাৰ্থনাৰ দুটা ৰাক'আতৰ পিছত, অনুমতিপ্ৰাপ্ত বিষয়ত আটাইতকৈ ভাল কি বিচাৰিবলৈ।", "নবী ছলীহ আলীহ ৱাছলে সাহাবীসকলক সকলো বিষয়ত ইস্তিকাৰা শিকোৱাৰ লগতে তেওঁ তেওঁলোকক কোৰাণৰ এটা ছুৰাহ শিকোৱাৰ লগতে।"),
        "dua_allahumma_bika_asbahna" to DuaText("আল্লাহুম্মা বীকা আসবাহনা", "হে আল্লাহ, আমি তোমাৰ দ্বাৰা ৰাতিপুৱা প্ৰৱেশ কৰোঁ আৰু তোমাৰ দ্বাৰা আমি সন্ধিয়া প্ৰৱেশ কৰোঁ; তোমাৰ দ্বাৰাই আমি জীয়াই আছোঁ আৰু তোমাৰ দ্বাৰা আমি মৰিছো, আৰু তোমাৰ বাবেই পুনৰুত্থান।", "ৰাতিপুৱা।", "নবী (ছাঃ)-এ আজি ৰাতিপুৱা আৰু সন্ধিয়া সাহাবীসকলক ক'বলৈ শিকাইছিল।"),
        "dua_allahumma_bika_amsayna" to DuaText("আল্লাহুম্মা বীকা আম্শেনা", "হে আল্লাহ, আমি তোমাৰ দ্বাৰা সন্ধিয়া প্ৰৱেশ কৰোঁ আৰু তোমাৰ দ্বাৰা আমি ৰাতিপুৱা প্ৰৱেশ কৰোঁ; আমি তোমাৰ দ্বাৰাই জীয়াই আছোঁ আৰু তোমাৰ দ্বাৰাই আমি মৰিছো, আৰু তোমাৰ ওচৰতে উভতি অহা।", "সন্ধিয়া।", "নবী (ছাঃ)-এ আজি ৰাতিপুৱা আৰু সন্ধিয়া সাহাবীসকলক ক'বলৈ শিকাইছিল।"),
        "dua_afiyah_morning" to DuaText("আফিয়াৰ বাবে সোধা", "হে আল্লাহ, মই এই পৃথিৱী আৰু পৰৱৰ্তী সময়ত ক্ষমা আৰু কল্যাণৰ বাবে তোমাৰ ওচৰত অনুৰোধ জনাইছো।", "নবী (ছাঃ)-এ কেতিয়াও এই দুআ ৰাতিপুৱা বা সন্ধিয়া এৰা নাছিল।", "কল্যাণতকৈ ভাল একো কাকো দিয়া হোৱা নাই।"),
        "dua_afini_fi_badani" to DuaText("শৰীৰ, শ্ৰৱণ আৰু দৃষ্টিশক্তিৰ স্বাস্থ্য", "হে আল্লাহ, মোৰ শৰীৰক সুস্থ কৰা। হে আল্লাহ, মোৰ শ্ৰৱণ শক্তি সু-সুস্থ কৰা। হে আল্লাহ, মোৰ দৃষ্টিশক্তি সু-সুস্থ কৰা। তোমাৰ বাহিৰে কোনো উপাস্য নাই।", "প্ৰতিদিনে ৰাতিপুৱা আৰু সন্ধিয়া তিনিবাৰকৈ।", "স্বাস্থ্য আৰু ইন্দ্ৰিয়ৰ সুৰক্ষাৰ বাবে এটা দুৱা।"),
        "dua_ya_hayyu_aslih" to DuaText("মোৰ সকলো বিষয় সংশোধন কৰক", "হে সৰ্বজীৱিত, হে পালনকাৰী, মই তোমাৰ দয়াৰে সহায় বিচাৰোঁঃ মোৰ সকলো কাম ঠিক কৰা আৰু চকু ফুৰাৰ বাবেও মোক মোৰ ওপৰত এৰি নিদিবা।", "নবী (ছা)-এ ফাতিমাক (আৰ. এ.) ৰাতিপুৱা আৰু সন্ধিয়া এই কথা ক'বলৈ পৰামৰ্শ দিছিল।", "প্ৰতিটো ক্ষেত্ৰতে আল্লাহৰ সহায় বিচাৰি।"),
        "dua_subhanallah_adada_khalqihi" to DuaText("জুৱাইৰিয়াৰ তাছবীহ (আৰ. এ.)", "গৌৰৱ আল্লাহৰ আৰু সকলো প্ৰশংসা তেওঁৰ-তেওঁৰ সৃষ্টিৰ দৰে, যিমানেই তেওঁ সন্তুষ্ট হয়, তেওঁৰ সিংহাসনৰ ওজন আৰু তেওঁৰ বাক্যৰ চিয়াৰিৰ সমান।", "ৰাতিপুৱা তিনিবাৰ-ঘণ্টা ধিকৰতকৈ অধিক ওজন।", "এই চাৰিটা বাক্যাংশ তিনিবাৰ কোৱাটোৱে ৰাতিপুৱাৰ পৰা মধ্য ৰাতিপুৱালৈকে ধিকৰতকৈ অধিক গুৰুত্বপূৰ্ণ।"),
        "dua_salawat" to DuaText("দুৰুদ-ই-আব্ৰাহিম", "হে আল্লাহ, ইব্ৰাহিম আৰু ইব্ৰাহিমৰ পৰিয়ালৰ ওপৰত প্ৰাৰ্থনা প্ৰেৰণ কৰাৰ সময়ত মহম্মদ ছলীহ আলীহ ৱাছেলম আৰু মহম্মদৰ পৰিয়ালৰ ওপৰত প্ৰাৰ্থনা প্ৰেৰণ কৰক। আপুনি প্ৰশংসনীয়, গৌৰৱোজ্জ্বল। হে আল্লাহ, মহম্মদ ছলীহ আলীহ ৱাছেলম আৰু মহম্মদৰ পৰিয়ালক আশীৰ্বাদ দিয়ক, যেনেকৈ আপুনি ইব্ৰাহিম আৰু ইব্ৰাহিমৰ পৰিয়ালক আশীৰ্বাদ দিছিল; আপুনি প্ৰশংসনীয়, গৌৰৱোজ্জ্বল।", "প্ৰাৰ্থনাৰ সময়ত আৰু সকলো সময়তে নবী (ছাঃ)-ৰ ওপৰত ছালওয়াত।", "যিজনে এবাৰ চালাৱাট পঠিয়াই, আল্লাহে তেওঁৰ ওপৰত দহটা দয়া প্ৰেৰণ কৰে (মুছলমান 408)।"),
        "dua_wudu_after" to DuaText("ৱুডুৰ পিছত", "মই সাক্ষ্য দিছোঁ যে আল্লাহৰ বাহিৰে কোনোৰে উপাসনা কৰাৰ অধিকাৰ নাই, কেৱল, কোনো অংশীদাৰ অবিহনে, আৰু মহম্মদ ছলীহ আলীহ ছলম তেওঁৰ দাস আৰু ৰাছুল। হে আল্লাহ, মোক অনুতাপ কৰা আৰু নিজকে শুদ্ধ কৰা লোকসকলৰ ভিতৰত পৰিণত কৰা।", "ৱুডু সম্পূৰ্ণ কৰাৰ পিছত।", "তেওঁ যি ইচ্ছা প্ৰৱেশ কৰিবৰ বাবে স্বৰ্গৰ আঠটা দুৱাৰ মুকলি কৰা হয়।"),
        "dua_wudu_before" to DuaText("ৱুডুৰ আগতে", "আল্লাহৰ নামত।", "যেতিয়া ৱুডু আৰম্ভ কৰা হয়।", "যিজনে ইয়াৰ ওপৰত আল্লাহৰ নাম উল্লেখ নকৰে তেওঁৰ বাবে কোনো (সম্পূৰ্ণ) উডু নাই।"),
        "dua_istiftah" to DuaText("প্ৰাৰ্থনাৰ আৰম্ভণি (সানা)", "হে আল্লাহ, তোমাৰ গৌৰৱ আৰু প্ৰশংসা হওঁক। তোমাৰ নাম ধন্য, তোমাৰ মহিমা উচ্চ, আৰু তোমাৰ বাহিৰে কোনো ইলাহ নাই।", "প্ৰাৰ্থনাৰ আৰম্ভণিতে, উদ্বোধনী তাকবীৰৰ ঠিক পিছত।", "প্ৰাৰ্থনাৰ সুন্না আৰম্ভণিৰ দুআ।"),
        "dua_ruku" to DuaText("ৰুকুত", "মোৰ প্ৰভু, মহান প্ৰভুৰ গৌৰৱ হওক।", "ৰুকুত কমেও তিনিবাৰ।", "ৰুকুৰ সুন্নাহ তাসবিহ।"),
        "dua_sujood" to DuaText("সুজুদত", "মোৰ সৰ্বোচ্চ প্ৰভুৰ গৌৰৱ হওক।", "চুজুদত কমেও তিনিবাৰ।", "সিজদা কৰাৰ সময়ত দাসজন তেওঁৰ প্ৰভুৰ নিকটতম হয় (মুছলমান 482)।"),
        "dua_rising_ruku" to DuaText("ৰুকুৰ পৰা উঠা", "আল্লাহে তেওঁৰ কথা শুনিব যিজনে তেওঁৰ প্ৰশংসা কৰে। হে আমাৰ প্ৰভু, সকলো প্ৰশংসা তোমাৰ।", "ৰুকুৰ পৰা উঠি থিয় হৈ থকাৰ সময়ত।", "যিজনৰ'ৰব্বনা ৱা লাকাল-হামদ'দূতাসকলৰ সৈতে মিল হয়, তেওঁৰ অতীতৰ পাপসমূহ ক্ষমা কৰা হয়।"),
        "dua_between_sajdas" to DuaText("দুজন সাজদাসৰ মাজত", "হে মোৰ প্ৰভু, মোক ক্ষমা কৰা। হে মোৰ প্ৰভু, মোক ক্ষমা কৰা।", "দুটা প্ৰস্তাবৰ মাজত বহি থকাৰ সময়ত।", "প্ৰসাদৰ মাজত বহি থকাৰ সুন্নত দুআ।"),
        "dua_before_salam_four" to DuaText("চাৰিটা বস্তুৰ পৰা শৰণাৰ্থী (ছালামৰ আগতে)", "হে আল্লাহ, মই নৰকৰ শাস্তিৰ পৰা, কবৰৰ শাস্তিৰ পৰা, জীৱন-মৃত্যুৰ পৰীক্ষাৰ পৰা, আৰু মিছা মেছিয়া (দজ্জল) ৰ পৰীক্ষাৰ দুষ্টতাৰ পৰা তোমাৰ আশ্ৰয় বিচাৰো।", "অন্তিম তাছাহুদ আৰু চালাৱাটৰ পিছত, ছালামৰ আগতে।", "নবী (ছাঃ)-এ এই চাৰিটা বস্তুৰ পৰা আশ্ৰয় লোৱাৰ আদেশ দিছিল।"),
        "dua_qunoot_witr" to DuaText("উইট্ৰত কুনুট", "হে আল্লাহ, তুমি পথ দেখুৱাই দিয়া লোকসকলৰ মাজত মোক পথ দেখুৱা, তুমি মোক কল্যাণ কৰি দিয়া লোকসকলৰ মাজত মোক কল্যাণ কৰা, তুমি মোক তোমাৰ যত্ন লোৱা লোকসকলৰ মাজত মোক লৈ যোৱা, তুমি যি দিছা তাত মোক আশীৰ্বাদ কৰা, আৰু তুমি যি আদেশ দিছা তাৰ বেয়াৰ পৰা মোক ৰক্ষা কৰা। তুমি আদেশ দিছা আৰু তোমাৰ বিৰুদ্ধে কোনো আদেশ দিয়া নাই, আৰু তুমি যাৰ লগত বন্ধুত্ব কৰা তাক কেতিয়াও অপমান কৰা নহয়। হে আমাৰ প্ৰভু, তুমি ধন্য আৰু মহান।", "উইতৰ প্ৰাৰ্থনাত-নবী ছলীহ আলীহ ৱাছলেমে হাছান ইবন আলী (ৰা.) ক এই শিক্ষা দিছিল।", "উইত্ৰৰ সুন্নাহ কুনুত। (হানাফিসকলৰ মাজত,'আল্লাহুম্মা ইন্না নস্তা'ইনুকা'ও সুপৰিচিত।)"),
        "dua_qunoot_hanafi" to DuaText("কুনুত (আল্লাহুম্মা ইন্না নস্তাইনুকা)", "হে আল্লাহ, আমি তোমাৰ সহায় আৰু ক্ষমা বিচাৰো, আমি তোমাৰ ওপৰত বিশ্বাস ৰাখিছো আৰু তোমাৰ ওপৰত নিৰ্ভৰ কৰি আছো, আমি উত্তম ধৰণে তোমাৰ প্ৰশংসা কৰোঁ, আমি তোমাক ধন্যবাদ জনাইছো আৰু অকৃতজ্ঞ নহয়, আৰু যিজনে তোমাৰ অবাধ্যতা কৰে আমি তাক এৰি দিওঁ। হে আল্লাহ, আমি কেৱল তোমাকহে উপাসনা কৰোঁ, আমি তোমাৰ প্ৰাৰ্থনা কৰোঁ আৰু সিজদা কৰোঁ, আমি তোমাৰ প্ৰতি দ্ৰুততা আৰু প্ৰচেষ্টা কৰোঁ, আমি তোমাৰ দয়াৰ আশা কৰোঁ আৰু তোমাৰ শাস্তিৰ ভয় কৰোঁ; নিশ্চিতভাৱে তোমাৰ শাস্তি কাৰোদ্ধাৰীসকলৰ ওচৰলৈ যাব।", "ৱিটাৰত-হানাফিসকলৰ অনুশীলন।", "কুনুতত উমৰ (আৰ. এ.) ৰ পৰা প্ৰতিবেদন দিয়া হৈছিল।"),
        "dua_sleep_aslamtu" to DuaText("শুৱাৰ আগতে শেষ শব্দসমূহ", "হে আল্লাহ, মই নিজকে তোমাৰ ওচৰত সমর্পণ কৰোঁ, মোৰ কাম তোমাৰ ওপৰত আৰোপ কৰোঁ আৰু তোমাৰ ওপৰত আশা আৰু তোমাৰ ভয়ৰ বাবে মোৰ পিঠি তোমাৰ সুৰক্ষাৰ বাবে সমৰ্পিত কৰোঁ। তোমাৰ বাহিৰে তোমাৰ পৰা কোনো আশ্ৰয় আৰু পলায়ন নাই। মই তোমাৰ গ্ৰন্থত বিশ্বাস কৰোঁ যিটো তুমি প্ৰকাশ কৰিলা আৰু তোমাৰ নবীৰ ওপৰত যি তুমি পঠিয়াইছা।", "ৱুডুৰ পিছত সোঁফালে শুৱা-শুৱাৰ আগতে শেষ শব্দ।", "যদি সেই নিশা তেওঁৰ মৃত্যু হয়, তেন্তে তেওঁ ফিত্ৰা (ইছলাম) ত মৃত্যুবৰণ কৰে।"),
        "dua_waking_night" to DuaText("ৰাতি জাগি উঠা", "কেৱল আল্লাহৰ বাহিৰে, কোনো অংশীদাৰ অবিহনে, পূজা কৰাৰ অধিকাৰ নাই। তেওঁৰ শাসন আৰু তেওঁৰ প্রশংসা, আৰু তেওঁ সকলো বস্তুৰ ওপৰত ক্ষমতা আছে। সকলো প্ৰশংসা আল্লাহৰ বাবে, গৌৰৱ আল্লাহৰ, আল্লাহৰ বাহিৰে পূজা কৰাৰ অধিকাৰ নাই, আল্লাহ সৰ্বশ্ৰেষ্ঠ, আৰু আল্লাহৰ বাহিৰে কোনো শক্তি বা শক্তি নাই। হে আল্লাহ, মোক ক্ষমা কৰি দিয়ক।", "ৰাতিৰ সময়ত জাগি উঠাৰ সময়ত।", "তেওঁৰ দুআৰ উত্তৰ দিয়া হয়, আৰু যদি তেওঁ উডু কৰে আৰু প্ৰাৰ্থনা কৰে, তেন্তে তেওঁৰ প্ৰাৰ্থনা গ্ৰহণ কৰা হয়।"),
        "dua_hamm_ibn_masud" to DuaText("দুৱা দুখৰ বাবে (ইবন মাছুদ)", "হে আল্লাহ, মই তোমাৰ দাস, তোমাৰ দাসৰ পুত্ৰ, তোমাৰ দাসীৰ পুত্ৰ। মোৰ আগৰ অংশ তোমাৰ হাতত আছে, মোৰ ওপৰত তোমাৰ আদেশ পালন কৰা হৈছে, আৰু মোৰ বিষয়ে তোমাৰ আদেশ ন্যায়সংগত। মই তোমাক তোমাৰ সকলো নামৰে সুধিম, যাৰে তুমি নিজকে নাম কৰিলা, বা তোমাৰ গ্ৰন্থত প্ৰকাশ কৰা, বা তোমাৰ সৃষ্টিৰ যিকোনোটোক শিকোৱা, বা অদৃশ্য জ্ঞানত তোমাৰ সৈতে ৰখা-যে তুমি কোৰাণক মোৰ হৃদয়ৰ উৎস, মোৰ বুকুৰ পোহৰ, মোৰ দুখ দূৰ কৰা আৰু মোৰ চিন্তাৰ নিৰ্মূল কৰা।", "দুখ আৰু দুখত-আল্লাহে দুখক আনন্দৰ সৈতে সলনি কৰে।", "আল্লাহে তেওঁৰ চিন্তা আৰু দুখ দূৰ কৰে আৰু তেওঁক তাৰ ঠাইত আনন্দ প্ৰদান কৰে।"),
        "dua_difficulty_sahl" to DuaText("যেতিয়া কিবা এটা কঠিন হয়", "হে আল্লাহ, আপুনি যি সহজ কৰে তাৰ বাহিৰে আন একো সহজ নহয়, আৰু আপুনি ইচ্ছা কৰিলে কঠিনটো সহজ কৰি তোলে।", "যেতিয়া কিবা এটা কঠিন অনুভৱ হয়।", "পৰীক্ষাত সহজ আৰু কঠিন কাম।"),
        "dua_musibah" to DuaText("অপন এ কেলেমিটি (ইষ্টিৰজা)", "আমি আল্লাহৰ আৰু আমি তেওঁৰ ওচৰতে ঘূৰি যাম। হে আল্লাহ, মোৰ দুখ-কষ্টত মোক পুৰস্কাৰ দিয়ক আৰু মোৰ বাবে ইয়াৰ ঠাইত কিবা ভাল বস্তু দিয়ক।", "যিকোনো ক্ষতি বা দুৰ্যোগৰ সময়ত।", "আল্লাহে নিশ্চয়কৈ কিছু ভাল দিয়ে-উম্ম ছালামাহ (আৰ. এ.) নবী ছলীহ আলীহ ৱাছলামক দিয়া হৈছিল।"),
        "dua_debt" to DuaText("ঋণৰ পৰা মুক্তিৰ বাবে", "হে আল্লাহ, তুমি যি অবৈধ কৰিছা তাৰ বিৰুদ্ধে তুমি যি বৈধ কৰিছা তাক লৈ মোক যথেষ্ট কৰা, আৰু তোমাৰ অনুগ্ৰহৰ দ্বাৰা মোক তোমাৰ বাহিৰে সকলোৰে পৰা স্বাধীন কৰা।", "ঋণ পৰিশোধৰ বাবে-আলী (আৰ. এ.) ৰ দ্বাৰা শিকোৱা।", "ঋণটো যদিও পাহাৰৰ দৰে হয়, তথাপিও আল্লাহে ইয়াক পৰিশোধ কৰিব।"),
        "dua_anger" to DuaText("যেতিয়া খং উঠে", "মই শাপিত শয়তানৰ পৰা আল্লাহৰ আশ্ৰয় বিচাৰো।", "যেতিয়া খং হয়।", "নবী (ছাঃ)-এ কৈছিলঃ যদি তেওঁ এই কথা কয়, তেন্তে তেওঁৰ খং আঁতৰি যাব।"),
        "dua_waswasa" to DuaText("বিশ্বাসত ৱাশ্বাসাৰ বিৰুদ্ধে", "মই আল্লাহ আৰু তেওঁৰ ৰসূলত বিশ্বাস কৰোঁ।", "যেতিয়া শয়তানৰ বিশ্বাসৰ বিষয়ে ফিসফিস কৰা হয়।", "যেতিয়া ফিসফিস কৰা হয়, এই কথা কোৱা আৰু তাতেই ৰৈ যাওক (আৰু লগতে আল্লাহৰ আশ্ৰয় লোৱা)।"),
    )
}
